from pwn import *

def test_inputs():
    server = remote('crypto.chal.csaw.io', 8000)

    # Test inputs
    inputs = ["test", "Test", "TesT"]
    results = {}

    for inp in inputs:
        server.sendline(inp)
        response = server.recvline().strip()
        results[inp] = response.hex()

    server.close()
    return results

if __name__ == "__main__":
    results = test_inputs()
    for inp, output in results.items():
        print(f"Input: {inp}, Output (hex): {output}")

from pwn import *
import binascii

def decode_server_hex(hex_string):
    try:
        decoded_bytes = binascii.unhexlify(hex_string)
        try:
            decoded_text = decoded_bytes.decode('ascii')
            return decoded_text
        except UnicodeDecodeError:
            return "Binary or non-ASCII data detected."
    except binascii.Error:
        return "Invalid hexadecimal string provided."

